from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    store = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        if key not in store:
            return True
        _, wt = store[key]
        return t >= wt + ttl

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # purge if expired
            if key in store and is_expired(key, t):
                del store[key]
            if key in store:
                # update existing, move to end
                store[key] = (value, t)
                store.move_to_end(key)
            else:
                if len(store) >= capacity:
                    store.popitem(last=False)
                store[key] = (value, t)
                store.move_to_end(key)
        else:
            _, t, key = op
            if key in store and not is_expired(key, t):
                value, wt = store[key]
                store.move_to_end(key)
                results.append(value)
            else:
                if key in store:
                    del store[key]
                results.append(-1)

    return results

